"""Optional named-compound evidence viewer; prediction records stay unchanged."""
from __future__ import annotations

import html
import json
import re


def render_named_evidence_report(result, explanation, title, class_labels=None):
    context = result.get("report_context") or {}
    original = {key: value for key, value in result.items() if key != "report_context"}
    payload = json.dumps({"record": original, "context": context,
                          "explanation": explanation,
                          "class_labels": list(class_labels) if class_labels else None},
                         ensure_ascii=False)
    # JSON is embedded as inert data, with every HTML/script delimiter escaped.
    for char, escaped in [("&", "\\u0026"), ("<", "\\u003c"), (">", "\\u003e"), ("\u2028", "\\u2028"), ("\u2029", "\\u2029")]:
        payload = payload.replace(char, escaped)
    # Replace tokens only in the template, never inside user-supplied text.
    values = {"TITLE": html.escape(title), "PAYLOAD": payload}
    return re.sub(r"__(TITLE|PAYLOAD)__", lambda match: values[match[1]], _TEMPLATE)


